CREATE TABLE IF NOT EXISTS public.tg_poligono_cic_info (
  codigo_poligono text PRIMARY KEY,
  lote_empresa text,
  version text,
  n_cic text,
  cic_difusion text,
  fotografias_difusion text,
  cic_inicio text,
  fotografias_inicio text,
  cic_cierre text,
  fotografias_cierre text,
  distrito_csv text,
  sector_csv text,
  fuente_csv text,
  actualizado_en timestamp DEFAULT now()
);
TRUNCATE public.tg_poligono_cic_info;

-- Vista sugerida para unir tu geometría con la información CIC del CSV.
CREATE OR REPLACE VIEW public.vw_tg_poligono_cic AS
SELECT
  p.*,
  COALESCE(NULLIF(i.lote_empresa,''), p."lote / empresa") AS lote_empresa_csv,
  COALESCE(NULLIF(i.version,''), p.version) AS version_csv,
  COALESCE(NULLIF(i.n_cic,''), p."n° cic"::text) AS n_cic_csv,
  COALESCE(NULLIF(i.cic_difusion,''), p."cic difusion"::text) AS cic_difusion_csv,
  COALESCE(NULLIF(i.cic_inicio,''), p."cic inicio"::text) AS cic_inicio_csv,
  COALESCE(NULLIF(i.cic_cierre,''), p."cic cierre"::text) AS cic_cierre_csv
FROM public.tg_poligono p
LEFT JOIN public.tg_poligono_cic_info i
  ON p.codigo_poligono::text = i.codigo_poligono;
